/**
 * Durable per-session turn ownership: `activeTurns` is in-memory, so servers
 * sharing a state root would otherwise both run the same session.
 *
 * Exclusion and liveness refresh come from `proper-lockfile`, which the
 * monorepo already uses for the git cache. Taking an abandoned lock over is
 * handled here, because the library does it by removing the stale lock and
 * then creating its own, and contenders that interleave those two steps each
 * come away holding the session.
 *
 * Liveness is lock age, not pid: containers have separate PID namespaces.
 */
import { randomUUID } from "node:crypto";
import { mkdir, rename, rm, stat } from "node:fs/promises";
import { join } from "node:path";
import * as lockfile from "proper-lockfile";
/** Long enough that the library never runs its own takeover. */
const NEVER_STALE_MS = 365 * 24 * 60 * 60_000;
/** Reject path traversal; session ids are opaque strings from the caller. */
function safeKey(sessionId) {
    const sanitized = sessionId
        .trim()
        .replace(/[^a-zA-Z0-9._-]+/g, "_")
        .replace(/^\.+/, "")
        .replace(/\.+/g, "_")
        .slice(0, 180);
    return sanitized === "" ? "_empty" : sanitized;
}
export class TurnLeaseStore {
    constructor(dir, options = {}) {
        /** Locks this process holds. Their release closures cannot live on disk. */
        this.held = new Map();
        this.dir = dir;
        // Several refreshes, so a slow owner is not mistaken for a dead one.
        this.staleMs = options.ttlMs ?? 30_000;
    }
    path(sessionId) {
        return join(this.dir, `${safeKey(sessionId)}.lease`);
    }
    /**
     * Undefined when another process holds this session and is still refreshing.
     *
     * `onCompromised` fires when the lock is lost mid-turn — the owner stalled
     * past the stale window and a successor took over. No lease scheme can stop
     * that; the callback is how the displaced turn learns to stand down instead
     * of answering alongside its successor.
     */
    async acquire(sessionId, onCompromised) {
        const existing = this.held.get(sessionId);
        if (existing !== undefined) {
            existing.refs += 1;
            return this.handle(sessionId);
        }
        await mkdir(this.dir, { recursive: true });
        const path = this.path(sessionId);
        await this.evictStaleLock(path);
        let release;
        try {
            release = await lockfile.lock(path, {
                realpath: false,
                retries: 0,
                stale: NEVER_STALE_MS,
                // How often the library refreshes the lock's mtime while we hold it.
                update: 5_000,
                onCompromised: () => {
                    this.held.delete(sessionId);
                    onCompromised?.();
                },
            });
        }
        catch {
            // Held elsewhere, or the store is unusable. Either way this process must
            // not run the turn: coalescing costs latency, two servers on one session
            // costs the conversation.
            return undefined;
        }
        this.held.set(sessionId, { release, refs: 1 });
        return this.handle(sessionId);
    }
    /**
     * Clear an abandoned lock, leaving a claim itself a single atomic `mkdir`.
     * Only the contender holding the takeover removes anything, and no claim can
     * land on an occupied path meanwhile, so the rest just race that `mkdir`.
     */
    async evictStaleLock(path) {
        // proper-lockfile's own naming for the lock it creates.
        const lockPath = `${path}.lock`;
        if (!(await this.isStale(lockPath))) {
            return;
        }
        const takeoverPath = `${path}.takeover`;
        if (await this.isStale(takeoverPath)) {
            // Left by a process that died mid-takeover. Grabbing it by rename admits
            // one clearer, where checking and then removing would admit several.
            const abandoned = `${takeoverPath}.${randomUUID()}`;
            try {
                await rename(takeoverPath, abandoned);
            }
            catch {
                return;
            }
            await rm(abandoned, { recursive: true, force: true });
        }
        try {
            await mkdir(takeoverPath);
        }
        catch {
            return;
        }
        try {
            // A successor may have claimed the session while this contender queued.
            if (await this.isStale(lockPath)) {
                await rm(lockPath, { recursive: true, force: true });
            }
        }
        finally {
            await rm(takeoverPath, { recursive: true, force: true });
        }
    }
    async isStale(lockPath) {
        const entry = await stat(lockPath).catch(() => undefined);
        return entry !== undefined && entry.mtimeMs < Date.now() - this.staleMs;
    }
    handle(sessionId) {
        let released = false;
        return {
            release: async () => {
                if (released) {
                    return;
                }
                released = true;
                const lock = this.held.get(sessionId);
                if (lock === undefined) {
                    return;
                }
                lock.refs -= 1;
                if (lock.refs > 0) {
                    return;
                }
                this.held.delete(sessionId);
                // Throws if the lock was already compromised, which is not our problem
                // to solve here: the successor owns it.
                await lock.release().catch(() => { });
            },
        };
    }
    /** Graceful shutdown: drop every claim so a successor need not wait it out. */
    async releaseAll() {
        for (const [sessionId, lock] of [...this.held]) {
            this.held.delete(sessionId);
            await lock.release().catch(() => { });
        }
    }
    /**
     * The session is running in another server process. Mirrors the engine's
     * in-memory `isTurnRunning`, which only ever sees this process.
     */
    async runningElsewhere(sessionId) {
        if (this.held.has(sessionId)) {
            return false;
        }
        try {
            return await lockfile.check(this.path(sessionId), {
                realpath: false,
                stale: this.staleMs,
            });
        }
        catch {
            return false;
        }
    }
}
